namespace papertrail { class FolderTree { public: FolderTree(); ~FolderTree(); FolderTree(const FolderTree&) = delete; FolderTree& operator=(const FolderTree&) = delete; FolderTree(FolderTree&&) = delete; FolderTree& operator=(FolderTree&&) = delete; /* Returns the entry type and a FileID or FolderID, with O(1) expected path lookup. */ PathLookupResult findPath(const char* path) const; StatusCode createFolder(const char* parent,const char* name); StatusCode insertDocument(const char* parent,FileID file,const char* name); StatusCode removeEntry(const char* path); /** Enumerates all document IDs within a live document or folder subtree, without transferring ownership. */ StatusCode enumerateDocumentsInSubtree(const char* path, DynamicArray<FileID>& output) const; StatusCode getParent(const char* path,FolderID& output) const; ExplorerListResult listChildren(const char* path,SortKey key=SortKey::Name,SortDirection direction=SortDirection::Ascending) const; BinResult moveToBin(const char* path,BinID bin); BinResult restoreFromBin(BinID bin,const char* destination,const char* name); /** Permanently deletes one BIN ITEM, not a live path; reports its contained FileIDs to callers before owned documents are freed. */ StatusCode permanentlyDeleteBinItem(BinID bin,DynamicArray<FileID>& deletedDocuments); DiagnosticResult validate() const; private: struct Node; Node* root_{}; }; }
